WITH MIV AS 
	( 
		SELECT 
			  UPPER(SHA2(  TO_CHAR(DVO_SRC1.COMPANY_HKEY) || '\\\\#' || TO_CHAR(DVO_SRC3.CONTACT_HKEY) || '\\\\#' || TO_CHAR(DVO_SRC5.VW_EVENT_HKEY)
				||'\\\\#' || TO_CHAR(DVO_SRC10.LEAD_HKEY) || '\\\\#' || TO_CHAR(DVO_SRC11.SCHEDULEDITEMS_HKEY) || '\\\\#' || TO_CHAR(DVO_SRC12.USER_HKEY) || '\\\\#' || TO_CHAR(DVO_SRC13.COMPANY_HKEY) || '\\\\#' || TO_CHAR(DVO_SRC16.HR_REPRESENTATIVE_HKEY) || '\\\\#' || TO_CHAR(DVO_SRC17.COMPANY_HKEY) || '\\\\#'  )) AS BRG_CLIENT_VISITS_HKEY
			, BVLCI_SRC.LOAD_DATE AS LOAD_DATE
			, BVLCI_SRC.LOAD_CYCLE_ID AS LOAD_CYCLE_ID
			, DVO_SRC1.COMPANY_HKEY AS COMPANY_HKEY_CONTACT
			, DVO_SRC3.CONTACT_HKEY AS CONTACT_HKEY
			, DVO_SRC5.VW_EVENT_HKEY AS VW_EVENT_HKEY
			, DVO_SRC10.LEAD_HKEY AS LEAD_HKEY
			, DVO_SRC11.SCHEDULEDITEMS_HKEY AS SCHEDULEDITEMS_HKEY
			, DVO_SRC12.USER_HKEY AS USER_HKEY
			, DVO_SRC13.COMPANY_HKEY AS COMPANY_HKEY_EVENT
			, DVO_SRC16.HR_REPRESENTATIVE_HKEY AS HR_REPRESENTATIVE_HKEY
			, DVO_SRC17.COMPANY_HKEY AS COMPANY_HKEY_EVENT_PARENT
            , DVO_SRC19.COMPANY_HKEY AS COMPANY_HKEY_CONTACT_PARENT
			, DVO_SRC2.LNK_CONTACT_COMPANY_HKEY AS LNK_CONTACT_COMPANY_HKEY
			, DVO_SRC4.LNK_VWEVENT_CONTACT_HKEY AS LNK_VWEVENT_CONTACT_HKEY
			, DVO_SRC6.LNK_VWEVENT_LEAD_HKEY AS LNK_VWEVENT_LEAD_HKEY
			, DVO_SRC7.LNK_VWEVENT_COMPANY_HKEY AS LNK_VWEVENT_COMPANY_HKEY
			, DVO_SRC8.LNK_VWEVENT_USER_OWNERID_HKEY AS LNK_VWEVENT_USER_OWNERID_HKEY
			, DVO_SRC9.LNA_VWEVENT_SCHEDULEDITEMS_HKEY AS LNA_VWEVENT_SCHEDULEDITEMS_HKEY
			, DVO_SRC14.LNK_SCHEDULEDITEMS_HRREPRESENTATIVE_HKEY AS LNK_SCHEDULEDITEMS_HRREPRESENTATIVE_HKEY
			, DVO_SRC15.LNK_COMPANY_COMPANY_PARENTID_HKEY AS LNK_COMPANY_COMPANY_PARENTID_HKEY_EVENT
            , DVO_SRC18.LNK_COMPANY_COMPANY_PARENTID_HKEY AS LNK_COMPANY_COMPANY_PARENTID_HKEY_CONTACT
			, DVO_SRC5.ID_BK AS VWEVENT_ID_BK
			, DVO_SRC10.ID_BK AS LEAD_ID_BK
			, DVO_SRC11.ITEMID_BK AS ITEMID_BK
			, DVO_SRC1.COMPANY_BK AS COMPANY_BK_CONTACT
			, DVO_SRC3.CONTACT_BK AS CONTACT_BK
			, DVO_SRC12.USER_BK AS USER_BK
			, DVO_SRC13.COMPANY_BK AS COMPANY_BK_EVENT
			, DVO_SRC16.HR_REPRESENTATIVE_BK AS HR_REPRESENTATIVE_BK
			, DVO_SRC17.COMPANY_BK AS COMPANY_BK_EVENT_PARENT
            , DVO_SRC19.COMPANY_BK AS COMPANY_BK_CONTACT_PARENT
		FROM ELIASSEN_DW.ELIASSEN_FMC.LOAD_CYCLE_INFO BVLCI_SRC
		INNER JOIN {{ source('eli_dv_bv', 'hub_company') }} DVO_SRC1 ON 1 = 1
		INNER JOIN {{ source('eli_dv_bv', 'lnk_contact_company') }} DVO_SRC2 ON DVO_SRC2.COMPANY_HKEY = DVO_SRC1.COMPANY_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'hub_contact') }} DVO_SRC3 ON DVO_SRC3.CONTACT_HKEY = DVO_SRC2.CONTACT_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'lnk_vwevent_contact') }} DVO_SRC4 ON DVO_SRC4.CONTACT_HKEY = DVO_SRC3.CONTACT_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'hub_vw_event') }} DVO_SRC5 ON DVO_SRC5.VW_EVENT_HKEY = DVO_SRC4.VW_EVENT_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'lnk_vwevent_lead') }} DVO_SRC6 ON DVO_SRC6.VW_EVENT_HKEY = DVO_SRC5.VW_EVENT_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'lnk_vwevent_company') }} DVO_SRC7 ON DVO_SRC7.VW_EVENT_HKEY = DVO_SRC5.VW_EVENT_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'lnk_vwevent_user_ownerid') }} DVO_SRC8 ON DVO_SRC8.VW_EVENT_HKEY = DVO_SRC5.VW_EVENT_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'view_lna_vwevent_scheduleditems') }} DVO_SRC9 ON DVO_SRC9.VW_EVENT_HKEY = DVO_SRC5.VW_EVENT_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'hub_lead') }} DVO_SRC10 ON DVO_SRC10.LEAD_HKEY = DVO_SRC6.LEAD_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'hub_scheduleditems') }} DVO_SRC11 ON DVO_SRC11.SCHEDULEDITEMS_HKEY = DVO_SRC9.SCHEDULEDITEMS_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'hub_user') }} DVO_SRC12 ON DVO_SRC12.USER_HKEY = DVO_SRC8.USER_OWNERID_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'hub_company') }} DVO_SRC13 ON DVO_SRC13.COMPANY_HKEY = DVO_SRC7.COMPANY_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'lnk_scheduleditems_hrrepresentative') }} DVO_SRC14 ON DVO_SRC14.SCHEDULEDITEMS_HKEY = DVO_SRC11.SCHEDULEDITEMS_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'lnk_company_company_parentid') }} DVO_SRC15 ON DVO_SRC15.COMPANY_HKEY = DVO_SRC13.COMPANY_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'hub_hr_representative') }} DVO_SRC16 ON DVO_SRC16.HR_REPRESENTATIVE_HKEY = DVO_SRC14.HR_REPRESENTATIVE_HKEY
		INNER JOIN {{ source('eli_dv_bv', 'hub_company') }} DVO_SRC17 ON DVO_SRC17.COMPANY_HKEY = DVO_SRC15.COMPANY_PARENTID_HKEY
        INNER JOIN {{ source('eli_dv_bv', 'lnk_company_company_parentid') }} DVO_SRC18 ON DVO_SRC18.COMPANY_HKEY = DVO_SRC1.COMPANY_HKEY
        INNER JOIN {{ source('eli_dv_bv', 'hub_company') }} DVO_SRC19 ON DVO_SRC19.COMPANY_HKEY = DVO_SRC18.COMPANY_PARENTID_HKEY
	)
	SELECT 
		  MIV.BRG_CLIENT_VISITS_HKEY AS BRG_CLIENT_VISITS_HKEY
		, MIV.LOAD_DATE AS LOAD_DATE
		, MIV.LOAD_CYCLE_ID AS LOAD_CYCLE_ID
		, MIV.USER_HKEY AS USER_HKEY
		, MIV.COMPANY_HKEY_EVENT AS COMPANY_HKEY_EVENT
		, MIV.COMPANY_HKEY_EVENT_PARENT AS COMPANY_HKEY_EVENT_PARENT
        , MIV.COMPANY_HKEY_CONTACT_PARENT AS COMPANY_HKEY_CONTACT_PARENT
		, MIV.COMPANY_HKEY_CONTACT AS COMPANY_HKEY_CONTACT
		, MIV.CONTACT_HKEY AS CONTACT_HKEY
		, MIV.HR_REPRESENTATIVE_HKEY AS HR_REPRESENTATIVE_HKEY
		, MIV.SCHEDULEDITEMS_HKEY AS SCHEDULEDITEMS_HKEY
		, MIV.LEAD_HKEY AS LEAD_HKEY
		, MIV.VW_EVENT_HKEY AS VW_EVENT_HKEY
		, MIV.LNK_CONTACT_COMPANY_HKEY AS LNK_CONTACT_COMPANY_HKEY
		, MIV.LNK_COMPANY_COMPANY_PARENTID_HKEY_EVENT AS LNK_COMPANY_COMPANY_PARENTID_HKEY_EVENT
        , MIV.LNK_COMPANY_COMPANY_PARENTID_HKEY_CONTACT AS LNK_COMPANY_COMPANY_PARENTID_HKEY_CONTACT
		, MIV.LNA_VWEVENT_SCHEDULEDITEMS_HKEY AS LNA_VWEVENT_SCHEDULEDITEMS_HKEY
		, MIV.LNK_SCHEDULEDITEMS_HRREPRESENTATIVE_HKEY AS LNK_SCHEDULEDITEMS_HRREPRESENTATIVE_HKEY
		, MIV.LNK_VWEVENT_LEAD_HKEY AS LNK_VWEVENT_LEAD_HKEY
		, MIV.LNK_VWEVENT_COMPANY_HKEY AS LNK_VWEVENT_COMPANY_HKEY
		, MIV.LNK_VWEVENT_CONTACT_HKEY AS LNK_VWEVENT_CONTACT_HKEY
		, MIV.LNK_VWEVENT_USER_OWNERID_HKEY AS LNK_VWEVENT_USER_OWNERID_HKEY
		, MIV.ITEMID_BK AS ITEMID_BK
		, MIV.LEAD_ID_BK AS LEAD_ID_BK
		, MIV.VWEVENT_ID_BK AS VWEVENT_ID_BK
		, MIV.USER_BK AS USER_BK
		, MIV.COMPANY_BK_EVENT_PARENT AS COMPANY_BK_EVENT_PARENT
        , MIV.COMPANY_BK_CONTACT_PARENT AS COMPANY_BK_CONTACT_PARENT
		, MIV.COMPANY_BK_CONTACT AS COMPANY_BK_CONTACT
		, MIV.COMPANY_BK_EVENT AS COMPANY_BK_EVENT
		, MIV.CONTACT_BK AS CONTACT_BK
		, MIV.HR_REPRESENTATIVE_BK AS HR_REPRESENTATIVE_BK
	FROM MIV MIV